sp_widget.css:
.tm-stats-container {
    display: flex;
    flex-wrap: wrap;
    gap: 16px;
    padding: 8px 0;
}

.stat-card {
    position: relative;
    flex: 1;
    min-width: 190px;
    height: 138px;
    border-radius: 20px;
    padding: 20px 24px;
    overflow: hidden;
    color: #fff;
    transition: all 0.3s ease;
    box-shadow: 0 10px 25px rgba(0,0,0,0.12);
    display: flex;
    align-items: flex-end;
}

.stat-card:hover {
    transform: translateY(-6px);
    box-shadow: 0 16px 35px rgba(0,0,0,0.2);
}

.card-icon {
    position: absolute;
    top: 18px;
    right: 18px;
    width: 52px;
    height: 52px;
    border-radius: 50%;
    background: rgba(255,255,255,0.18);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 26px;
    backdrop-filter: blur(4px);
}

.card-content {
    width: 100%;
}

.label {
    display: block;
    font-size: 11.5px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.8px;
    opacity: 0.85;
    margin-bottom: 2px;
}

.card-content h2 {
    font-size: 42px;
    font-weight: 700;
    line-height: 1;
    margin: 4px 0 6px 0;
}

.sub-text {
    font-size: 12.5px;
    opacity: 0.9;
    font-weight: 500;
}

/* Premium Gradients */
.residents { background: linear-gradient(135deg, #2563eb, #60a5fa); }
.schedules { background: linear-gradient(135deg, #0891b2, #22d3ee); }
.completed { background: linear-gradient(135deg, #059669, #34d399); }
.pending   { background: linear-gradient(135deg, #d97706, #fbbf24); }
.missed    { background: linear-gradient(135deg, #dc2626, #fb7185); }

/* Subtle Decorative Elements */
.stat-card::before {
    content: '';
    position: absolute;
    width: 140px;
    height: 140px;
    background: rgba(255,255,255,0.12);
    border-radius: 50%;
    top: -55px;
    right: -55px;
    z-index: 0;
}

.stat-card::after {
    content: '';
    position: absolute;
    width: 90px;
    height: 90px;
    background: rgba(255,255,255,0.08);
    border-radius: 50%;
    bottom: -45px;
    left: -35px;
    z-index: 0;
}

sp_widget.script:
(function() {

    data.today = new GlideDate().getDisplayValue();
    data.user = gs.getUserDisplayName();

    data.residents = 0;
    data.schedules = 0;
    data.completed = 0;
    data.pending = 0;
    data.missed = 0;

    var patients = {};

    var gr = new GlideRecord('x_snc_trackmed_medication_schedule_table');

    // Restrict only non-admin users
    if (!(gs.hasRole('admin') || gs.hasRole('x_snc_trackmed.admin'))) {
        gr.addQuery('caretaker', gs.getUserID());
    }

    gr.query();

    while (gr.next()) {

        // Count unique patients
        if (gr.patient)
            patients[gr.patient.toString()] = true;

        data.schedules++;

        var state = gr.getValue('state');

        switch (state) {
            case 'completed':
                data.completed++;
                break;

            case 'pending':
                data.pending++;
                break;

            case 'missed':
                data.missed++;
                break;
        }
    }

    data.residents = Object.keys(patients).length;

})();
